/* Signature Hebrew Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Noamtal": "From noam (pleasantness) + tal (dew): 'pleasant dew'.", "Yaelshir": "From Yael + shir (song).", "Eitanaviv": "From eitan (strong) + aviv (spring): 'strong spring'.", "Talor": "From tal (dew) + or (light): 'dew light'.", "Shiranur": "From shira (song) + nur? built on or (light).", "Avivgal": "From aviv (spring) + gal (wave): 'spring wave'.", "Ben-Noamtal": "Signature surname in ben style.", "Talori": "Signature surname in -i style: 'of dew-light'.", "Avivgalon": "Signature surname in -on style.", "Shironi": "Signature surname: 'of my song'."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Noamtal';
console.log(lookup(q));

